\pset footer off
\echo ===J credential drilldowns
SELECT 'null-actor creds by type: '||type AS chk, count(*) FROM credential WHERE "actorId" IS NULL GROUP BY type
UNION ALL SELECT 'expired creds by type: '||type, count(*) FROM credential WHERE expires IS NOT NULL AND expires<now() GROUP BY type
UNION ALL SELECT 'expired AND null actor', count(*) FROM credential WHERE expires IS NOT NULL AND expires<now() AND "actorId" IS NULL
UNION ALL SELECT 'dup creds by type: '||type, count(*) FROM (SELECT type FROM credential GROUP BY "actorId",type,"resourceID" HAVING count(*)>1) d GROUP BY type
UNION ALL SELECT 'missing-space creds by type: '||type, count(*) FROM credential c WHERE c.type LIKE 'space-%' AND NOT EXISTS (SELECT 1 FROM space s WHERE s.id::text=c."resourceID") GROUP BY type
UNION ALL SELECT 'missing-space creds pointing at template_content_space', count(*) FROM credential c WHERE c.type LIKE 'space-%' AND NOT EXISTS (SELECT 1 FROM space s WHERE s.id::text=c."resourceID") AND EXISTS (SELECT 1 FROM template_content_space t WHERE t.id::text=c."resourceID")
UNION ALL SELECT 'missing-org creds by type: '||type, count(*) FROM credential c WHERE c.type LIKE 'organization-%' AND NOT EXISTS (SELECT 1 FROM organization o WHERE o.id::text=c."resourceID") GROUP BY type
UNION ALL SELECT 'missing-account creds by type: '||type, count(*) FROM credential c WHERE c.type LIKE 'account-%' AND NOT EXISTS (SELECT 1 FROM account a WHERE a.id::text=c."resourceID") GROUP BY type
UNION ALL SELECT 'space-admin w/o member by actor type: '||a.type, count(*) FROM credential c JOIN actor a ON a.id=c."actorId" WHERE c.type='space-admin' AND NOT EXISTS (SELECT 1 FROM credential m WHERE m."actorId"=c."actorId" AND m.type='space-member' AND m."resourceID"=c."resourceID") GROUP BY a.type
UNION ALL SELECT 'space-lead w/o member by actor type: '||a.type, count(*) FROM credential c JOIN actor a ON a.id=c."actorId" WHERE c.type='space-lead' AND NOT EXISTS (SELECT 1 FROM credential m WHERE m."actorId"=c."actorId" AND m.type='space-member' AND m."resourceID"=c."resourceID") GROUP BY a.type
UNION ALL SELECT 'org owner/admin w/o associate by role: '||c.type, count(*) FROM credential c WHERE c.type IN ('organization-owner','organization-admin') AND NOT EXISTS (SELECT 1 FROM credential m WHERE m."actorId"=c."actorId" AND m.type='organization-associate' AND m."resourceID"=c."resourceID") GROUP BY c.type
UNION ALL SELECT 'org owner/admin w/o associate: distinct users', count(DISTINCT "actorId") FROM credential c WHERE c.type IN ('organization-owner','organization-admin') AND NOT EXISTS (SELECT 1 FROM credential m WHERE m."actorId"=c."actorId" AND m.type='organization-associate' AND m."resourceID"=c."resourceID")
UNION ALL SELECT 'space-subspace-admin -> missing space', count(*) FROM credential c WHERE c.type='space-subspace-admin' AND NOT EXISTS (SELECT 1 FROM space s WHERE s.id::text=c."resourceID")
UNION ALL SELECT 'space-subspace-admin held without space-admin on same space', count(*) FROM credential c WHERE c.type='space-subspace-admin' AND NOT EXISTS (SELECT 1 FROM credential m WHERE m."actorId"=c."actorId" AND m.type='space-admin' AND m."resourceID"=c."resourceID")
UNION ALL SELECT 'space-admin on L0 without space-subspace-admin', count(*) FROM credential c JOIN space s ON s.id::text=c."resourceID" WHERE c.type='space-admin' AND s.level=0 AND NOT EXISTS (SELECT 1 FROM credential m WHERE m."actorId"=c."actorId" AND m.type='space-subspace-admin' AND m."resourceID"=c."resourceID")
UNION ALL SELECT 'space-invitee creds whose actor has no pending invitation', count(*) FROM credential c WHERE c.type='space-invitee' AND NOT EXISTS (SELECT 1 FROM invitation i JOIN community cm ON cm."roleSetId"=i."roleSetId" JOIN space s ON s."communityId"=cm.id WHERE i."invitedActorId"=c."actorId" AND s.id::text=c."resourceID")
UNION ALL SELECT 'space-invitee creds where actor already member', count(*) FROM credential c WHERE c.type='space-invitee' AND EXISTS (SELECT 1 FROM credential m WHERE m."actorId"=c."actorId" AND m.type='space-member' AND m."resourceID"=c."resourceID")
UNION ALL SELECT 'license creds on space not matching space.license entitlements? (space-license-* count per space >1)', count(*) FROM (SELECT "actorId" FROM credential WHERE type LIKE 'space-license-%' GROUP BY 1 HAVING count(*)>1) d
UNION ALL SELECT 'L0 space without any space-license-* credential', count(*) FROM space s WHERE s.level=0 AND NOT EXISTS (SELECT 1 FROM credential c WHERE c."actorId"=s.id AND c.type LIKE 'space-license-%')
UNION ALL SELECT 'subspace holding a space-license-* credential', count(*) FROM space s WHERE s.level>0 AND EXISTS (SELECT 1 FROM credential c WHERE c."actorId"=s.id AND c.type LIKE 'space-license-%')
UNION ALL SELECT 'account without account-license-* credential', count(*) FROM account a WHERE NOT EXISTS (SELECT 1 FROM credential c WHERE c."actorId"=a.id AND c.type LIKE 'account-license-%')
UNION ALL SELECT 'account holding space-* credential (wrong actor)', count(*) FROM credential c JOIN actor a ON a.id=c."actorId" WHERE a.type='account' AND c.type LIKE 'space-%'
UNION ALL SELECT 'user without account-admin on own account', count(*) FROM "user" u WHERE NOT EXISTS (SELECT 1 FROM credential c WHERE c."actorId"=u.id AND c.type='account-admin' AND c."resourceID"=u."accountID"::text)
UNION ALL SELECT 'org owner without account-admin on org account', count(*) FROM credential o JOIN organization org ON org.id::text=o."resourceID" WHERE o.type='organization-owner' AND NOT EXISTS (SELECT 1 FROM credential c WHERE c."actorId"=o."actorId" AND c.type='account-admin' AND c."resourceID"=org."accountID"::text)
UNION ALL SELECT 'account-admin on account with no user/org owner link', count(*) FROM credential c WHERE c.type='account-admin' AND NOT EXISTS (SELECT 1 FROM "user" u WHERE u."accountID"::text=c."resourceID" AND u.id=c."actorId") AND NOT EXISTS (SELECT 1 FROM organization org JOIN credential o ON o."resourceID"=org.id::text AND o.type='organization-owner' AND o."actorId"=c."actorId" WHERE org."accountID"::text=c."resourceID");
\echo ===J subspace member without parent member: sample of 12 (user/org, space path)
SELECT a.type AS actor_type, a."nameID" AS actor, s.level, sub."nameID" AS subspace, par."nameID" AS parent, l0."nameID" AS l0, c."createdDate"::date
FROM credential c JOIN actor a ON a.id=c."actorId" JOIN space s ON s.id::text=c."resourceID" AND s.level>0 JOIN actor sub ON sub.id=s.id JOIN actor par ON par.id=s."parentSpaceId" JOIN actor l0 ON l0.id=s."levelZeroSpaceID"
WHERE c.type='space-member' AND NOT EXISTS (SELECT 1 FROM credential p WHERE p."actorId"=c."actorId" AND p.type='space-member' AND p."resourceID"=s."parentSpaceId"::text) ORDER BY c."createdDate" DESC LIMIT 12;
\echo ===J subspace member without parent member: by credential year
SELECT extract(year FROM c."createdDate") AS yr, count(*) FROM credential c JOIN space s ON s.id::text=c."resourceID" AND s.level>0 WHERE c.type='space-member' AND NOT EXISTS (SELECT 1 FROM credential p WHERE p."actorId"=c."actorId" AND p.type='space-member' AND p."resourceID"=s."parentSpaceId"::text) GROUP BY 1 ORDER BY 1;
\echo ===J role drilldowns
SELECT 'role.credential.resourceID != space by role: '||r.name AS chk, count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId" WHERE r.name IN ('member','lead','admin') AND r.credential->>'resourceID'<>s.id::text GROUP BY r.name
UNION ALL SELECT 'role.credential.resourceID points to another existing space', count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId" WHERE r.name IN ('member','lead','admin') AND r.credential->>'resourceID'<>s.id::text AND EXISTS (SELECT 1 FROM space o WHERE o.id::text=r.credential->>'resourceID')
UNION ALL SELECT 'role.credential.resourceID points to template_content_space', count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId" WHERE r.name IN ('member','lead','admin') AND r.credential->>'resourceID'<>s.id::text AND EXISTS (SELECT 1 FROM template_content_space o WHERE o.id::text=r.credential->>'resourceID')
UNION ALL SELECT 'role.credential.resourceID empty', count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId" WHERE r.credential->>'resourceID'=''
UNION ALL SELECT 'parentCredentials count != level by level '||s.level||' role '||r.name||' count '||jsonb_array_length(r."parentCredentials"), count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId" WHERE r.name IN ('member','lead','admin') AND jsonb_array_length(r."parentCredentials")<>s.level GROUP BY s.level, r.name, jsonb_array_length(r."parentCredentials")
UNION ALL SELECT 'parentCredentials not-ancestor by role: '||r.name, count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId", jsonb_array_elements(r."parentCredentials") e WHERE e->>'resourceID' NOT IN (s."parentSpaceId"::text, s."levelZeroSpaceID"::text) GROUP BY r.name
UNION ALL SELECT 'parentCredentials not-ancestor pointing at existing space', count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId", jsonb_array_elements(r."parentCredentials") e WHERE e->>'resourceID' NOT IN (s."parentSpaceId"::text, s."levelZeroSpaceID"::text) AND EXISTS (SELECT 1 FROM space o WHERE o.id::text=e->>'resourceID')
UNION ALL SELECT 'role_set not owned: referenced by template_content_space community', count(*) FROM role_set rs WHERE NOT EXISTS (SELECT 1 FROM community c WHERE c."roleSetId"=rs.id) AND NOT EXISTS (SELECT 1 FROM organization o WHERE o."roleSetId"=rs.id) AND NOT EXISTS (SELECT 1 FROM platform p WHERE p."roleSetId"=rs.id)
UNION ALL SELECT 'role_set not owned: type '||rs.type, count(*) FROM role_set rs WHERE NOT EXISTS (SELECT 1 FROM community c WHERE c."roleSetId"=rs.id) AND NOT EXISTS (SELECT 1 FROM organization o WHERE o."roleSetId"=rs.id) GROUP BY rs.type
UNION ALL SELECT 'communities not owned by a space', count(*) FROM community c WHERE NOT EXISTS (SELECT 1 FROM space s WHERE s."communityId"=c.id);
\echo ===J role.credential mismatch sample
SELECT sub."nameID" AS space, s.level, r.name, r.credential->>'resourceID' AS cred_resource, (SELECT o."nameID" FROM actor o WHERE o.id::text=r.credential->>'resourceID') AS points_to, r."createdDate"::date
FROM space s JOIN actor sub ON sub.id=s.id JOIN community c ON c.id=s."communityId" JOIN role r ON r."roleSetId"=c."roleSetId" WHERE r.name IN ('member','lead','admin') AND r.credential->>'resourceID'<>s.id::text ORDER BY r."createdDate" DESC LIMIT 10;
\echo ===J space hierarchy anomalies (rows)
SELECT 'L0 with parent' AS what, a."nameID", s.level, p."nameID" AS parent, s.visibility FROM space s JOIN actor a ON a.id=s.id LEFT JOIN actor p ON p.id=s."parentSpaceId" WHERE s.level=0 AND s."parentSpaceId" IS NOT NULL
UNION ALL SELECT 'level != parent+1', a."nameID", s.level, p."nameID"||' (L'||ps.level||')', s.visibility FROM space s JOIN actor a ON a.id=s.id JOIN space ps ON ps.id=s."parentSpaceId" JOIN actor p ON p.id=ps.id WHERE s.level<>ps.level+1
UNION ALL SELECT 'levelZero mismatch', a."nameID", s.level, z."nameID", s.visibility FROM (WITH RECURSIVE ch AS (SELECT id, id AS cur, "parentSpaceId" AS par FROM space UNION ALL SELECT ch.id, p.id, p."parentSpaceId" FROM ch JOIN space p ON p.id=ch.par) SELECT ch.id, ch.cur FROM ch JOIN space s ON s.id=ch.id WHERE ch.par IS NULL AND s."levelZeroSpaceID"<>ch.cur) x JOIN space s ON s.id=x.id JOIN actor a ON a.id=s.id JOIN actor z ON z.id=s."levelZeroSpaceID"
UNION ALL SELECT 'dup sibling nameID', a."nameID", s.level, coalesce(p."nameID",'<root>'), count(*)::text FROM space s JOIN actor a ON a.id=s.id LEFT JOIN actor p ON p.id=s."parentSpaceId" GROUP BY a."nameID", s.level, p."nameID", s."parentSpaceId" HAVING count(*)>1
UNION ALL SELECT 'subspace visibility != L0', a."nameID", s.level, z."nameID"||' ('||z2.visibility||')', s.visibility FROM space s JOIN actor a ON a.id=s.id JOIN space z2 ON z2.id=s."levelZeroSpaceID" JOIN actor z ON z.id=z2.id WHERE s.level>0 AND s.visibility<>z2.visibility;
\echo ===J storage aggregator anomalies
SELECT 'L0 aggregator parent != account aggregator: parent is null' AS chk, count(*) FROM space s JOIN account ac ON ac.id=s."accountId" JOIN storage_aggregator sa ON sa.id=s."storageAggregatorId" WHERE s.level=0 AND sa."parentStorageAggregatorId" IS NULL
UNION ALL SELECT 'L0 aggregator parent points to another account aggregator', count(*) FROM space s JOIN account ac ON ac.id=s."accountId" JOIN storage_aggregator sa ON sa.id=s."storageAggregatorId" WHERE s.level=0 AND sa."parentStorageAggregatorId" IS NOT NULL AND sa."parentStorageAggregatorId"<>ac."storageAggregatorId" AND EXISTS (SELECT 1 FROM account a2 WHERE a2."storageAggregatorId"=sa."parentStorageAggregatorId")
UNION ALL SELECT 'L0 aggregator parent points to a deleted aggregator', count(*) FROM space s JOIN storage_aggregator sa ON sa.id=s."storageAggregatorId" WHERE s.level=0 AND sa."parentStorageAggregatorId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM storage_aggregator p WHERE p.id=sa."parentStorageAggregatorId")
UNION ALL SELECT 'storage_aggregator parent dangling (any)', count(*) FROM storage_aggregator sa WHERE sa."parentStorageAggregatorId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM storage_aggregator p WHERE p.id=sa."parentStorageAggregatorId")
UNION ALL SELECT 'storage_aggregator without directStorage', count(*) FROM storage_aggregator WHERE "directStorageId" IS NULL
UNION ALL SELECT 'storage_aggregator types: '||type, count(*) FROM storage_aggregator GROUP BY type;
\echo ===J misc semantics checks
SELECT 'community.parentID values that are space ids' AS chk, count(*) FROM community c WHERE EXISTS (SELECT 1 FROM space s WHERE s.id::text=c."parentID")
UNION ALL SELECT 'community.parentID != owning space id', count(*) FROM space s JOIN community c ON c.id=s."communityId" WHERE c."parentID"<>s.id::text
UNION ALL SELECT 'communication.spaceID set but != owning space', count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN communication m ON m.id=c."communicationId" WHERE m."spaceID"<>'' AND m."spaceID"<>s.id::text
UNION ALL SELECT 'communication.spaceID empty for a space-owned communication', count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN communication m ON m.id=c."communicationId" WHERE m."spaceID"=''
UNION ALL SELECT 'communication.spaceID empty by L: '||s.level, count(*) FROM space s JOIN community c ON c.id=s."communityId" JOIN communication m ON m.id=c."communicationId" WHERE m."spaceID"='' GROUP BY s.level
UNION ALL SELECT 'homeSpace shapes: '||jsonb_typeof("homeSpace")||' keys '||coalesce((SELECT string_agg(k,',') FROM jsonb_object_keys(CASE WHEN jsonb_typeof("homeSpace")='object' THEN "homeSpace" ELSE '{}'::jsonb END) k),'-'), count(*) FROM user_settings GROUP BY 1
UNION ALL SELECT 'homeSpace.spaceID -> nonexistent space', count(*) FROM user_settings WHERE jsonb_typeof("homeSpace")='object' AND ("homeSpace"->>'spaceID') IS NOT NULL AND ("homeSpace"->>'spaceID')<>'' AND NOT EXISTS (SELECT 1 FROM space z WHERE z.id::text="homeSpace"->>'spaceID')
UNION ALL SELECT 'homeSpace.spaceID set but user not member', count(*) FROM user_settings us JOIN "user" u ON u."settingsId"=us.id WHERE ("homeSpace"->>'spaceID')<>'' AND NOT EXISTS (SELECT 1 FROM credential c WHERE c."actorId"=u.id AND c.type='space-member' AND c."resourceID"="homeSpace"->>'spaceID')
UNION ALL SELECT 'ai_persona orphans (no VC) by engine: '||coalesce(engine::text,'null'), count(*) FROM ai_persona p WHERE NOT EXISTS (SELECT 1 FROM virtual_contributor v WHERE v."aiPersonaID"=p.id) GROUP BY engine
UNION ALL SELECT 'activity orphan (collaboration gone) by type: '||type, count(*) FROM activity a WHERE NOT EXISTS (SELECT 1 FROM collaboration c WHERE c.id=a."collaborationID") GROUP BY type
UNION ALL SELECT 'user.authenticationID null: users', count(*) FROM "user" WHERE "authenticationID" IS NULL
UNION ALL SELECT 'user.serviceProfile true', count(*) FROM "user" WHERE "serviceProfile"=true
UNION ALL SELECT 'mcp_api_key -> deleted user: isActive', count(*) FROM mcp_api_key k WHERE NOT EXISTS (SELECT 1 FROM "user" u WHERE u.id=k."userId") AND k."isActive"=true
UNION ALL SELECT 'organization_verification orphan rows (no org)', count(*) FROM organization_verification v WHERE NOT EXISTS (SELECT 1 FROM organization o WHERE o."verificationId"=v.id)
UNION ALL SELECT 'file_backup_outbox dangling fileId', count(*) FROM file_backup_outbox b WHERE NOT EXISTS (SELECT 1 FROM file f WHERE f.id=b."fileId")
UNION ALL SELECT 'file_backup_outbox rows by status: '||coalesce(status::text,'?'), count(*) FROM file_backup_outbox GROUP BY status;
\echo ===J users with null authenticationID
SELECT a."nameID", u.email ~ '@' AS has_email, u."serviceProfile", a."createdDate"::date FROM "user" u JOIN actor a ON a.id=u.id WHERE u."authenticationID" IS NULL ORDER BY a."createdDate";
